namespace ToneCustoms.ShellStudio.Core;
public sealed class StarterTemplates { readonly GeometryService g=new(); public ShellProject Create(string type,string name){var p=new ShellProject{Name=name};if(type.Equals("Empty",StringComparison.OrdinalIgnoreCase))return p;var size=type.ToLowerInvariant() switch{"bedroom"=>(4f,4f),"apartment"=>(10f,8f),"house"=>(14f,12f),"store"=>(12f,8f),"office"=>(14f,10f),"warehouse"=>(24f,18f),"restaurant"=>(16f,12f),"club"=>(18f,14f),_=>(8f,8f)};p.Objects.Add(g.Floor(new(),size.Item1,size.Item2));p.Objects.Add(g.Ceiling(new(0,0,3),size.Item1,size.Item2));p.Objects.Add(g.Wall(new(0,-size.Item2/2,1.5f),size.Item1));p.Objects.Add(g.Wall(new(0,size.Item2/2,1.5f),size.Item1));return p;} }
